async function staticResponse(res,path,dir){const file=path==='/'?'index.html':path.slice(1);if(file.includes('..')||file.includes('\\'))return response(res,404,{error:{code:'not_found',message:'Not found'}});try{const target=resolve(dir,file),base=resolve(dir);if(!target.startsWith(base+'/'))return response(res,404,{error:{code:'not_found',message:'Not found'}});const data=await readFile(target),mime={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.mjs':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.svg':'image/svg+xml'}[extname(target)]||'application/octet-stream';res.writeHead(200,{'content-type':mime,'cache-control':'no-store','x-content-type-options':'nosniff','content-security-policy':"default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'self'; frame-ancestors 'none'"});res.end(data)}catch{response(res,404,{error:{code:'not_found',message:'Not found'}})}}
